const b = $input.first().json.body || $input.first().json;
const cap = str => str ? str.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') : '';
return [{
  json: {
    freelancer_name: cap(b.freelancer_name),
    freelancer_email: b.freelancer_email || '',
    client_name: cap(b.client_name),
    client_email: b.client_email || '',
    invoice_number: b.invoice_number || '',
    amount: b.amount || '',
    service: b.service || '',
    due_date: b.due_date || '',
    urgency: b.urgency || 'gentle',
    freelancer_address: b.freelancer_address || '',
    client_address: b.client_address || '',
    tax_rate: b.tax_rate || '',
    payment_method: b.payment_method || '',
    date_sent: new Date().toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }),
    status: 'Sent'
  }
}];

const d = $('Format Invoice Data').first().json;
const paymentMethod = d.payment_method || 'a method to be agreed';

const rawAmount = String(d.amount).replace(/[^0-9.]/g, '');
const subtotal = parseFloat(rawAmount) || 0;
const taxRate = parseFloat(d.tax_rate) || 0;
const taxAmount = Math.round((subtotal * taxRate / 100) * 100) / 100;
const total = Math.round((subtotal + taxAmount) * 100) / 100;

const fmt = n => '$' + n.toFixed(2);

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Georgia,serif;color:#1a1a1a;padding:56px;background:#fff}
.wrap{max-width:700px;margin:0 auto}

.brand{font-size:30px;font-weight:700;letter-spacing:0.5px;color:#111}
.brand-sub{font-size:12px;color:#999;margin-top:4px}
.meta{text-align:right;font-size:12px;color:#999}
.meta strong{display:block;font-size:14px;color:#111;margin-top:2px}

.parties{display:flex;justify-content:space-between;margin-bottom:36px}
.party{width:47%}
.label{font-size:11px;font-weight:700;color:#4f46e5;letter-spacing:0.5px;margin-bottom:6px;text-transform:uppercase}
.pname{font-size:15px;font-weight:700;margin-bottom:3px}
.pdetail{font-size:13px;color:#555;line-height:1.6}

.datesrow{display:flex;gap:40px;margin-bottom:32px}
.dateitem .label{margin-bottom:4px}
.dateval{font-size:14px;font-weight:700}

table.items{width:100%;border-collapse:collapse;margin-bottom:8px}
table.items th{text-align:left;font-size:11px;font-weight:700;color:#4f46e5;letter-spacing:0.5px;padding:0 0 10px;border-bottom:2px solid #4f46e5}
table.items th.r{text-align:right}
table.items td{padding:14px 0;font-size:14px;border-bottom:1px solid #eee}
table.items td.r{text-align:right;font-weight:600}

.totals{margin-left:auto;width:240px;margin-top:16px}
.totals table{width:100%;border-collapse:collapse}
.totals td{padding:6px 0;font-size:13px;color:#555}
.totals td.r{text-align:right}
.totals .total-row td{border-top:2px solid #4f46e5;padding-top:12px;font-size:17px;font-weight:700;color:#111}

.notes{margin-top:48px}
.notes .label{margin-bottom:8px}
.notes p{font-size:13px;color:#555;line-height:1.7;margin-bottom:6px}
</style></head><body>
<div class="wrap">

  <div class="top">
    <div>
      <div class="brand">INVOICE</div>
      <div class="brand-sub">#${d.invoice_number}</div>
    </div>
    <div class="meta">Date Issued<strong>${d.date_sent}</strong></div>
  </div>

  <div class="parties">
    <div class="party">
      <div class="label">From</div>
      <div class="pname">${d.freelancer_name}</div>
      <div class="pdetail">${d.freelancer_email}${d.freelancer_address ? '<br>' + d.freelancer_address : ''}</div>
    </div>
    <div class="party" style="text-align:right">
      <div class="label">To</div>
      <div class="pname">${d.client_name}</div>
      <div class="pdetail">${d.client_email}${d.client_address ? '<br>' + d.client_address : ''}</div>
    </div>
  </div>

  <div class="datesrow">
    <div class="dateitem"><div class="label">Due Date</div><div class="dateval">${d.due_date}</div></div>
  </div>

  <table class="items">
    <tr><th>Description</th><th class="r">Amount</th></tr>
    <tr><td>${d.service}</td><td class="r">${fmt(subtotal)}</td></tr>
  </table>

  <div class="totals">
    <table>
      <tr><td>Subtotal</td><td class="r">${fmt(subtotal)}</td></tr>
      ${taxRate > 0 ? `<tr><td>Tax (${taxRate}%)</td><td class="r">${fmt(taxAmount)}</td></tr>` : ''}
      <tr class="total-row"><td>Total</td><td class="r">${fmt(total)}</td></tr>
    </table>
  </div>

  <div class="notes">
    <div class="label">Notes</div>
    <p>Thank you for your business.</p>
    <p>Payment can be made via ${paymentMethod}. Please reply to this email for payment details or if you have any questions.</p>
  </div>

</div>
</body></html>`;

return [{ json: { ...d, html: html, calculated_total: fmt(total) } }];
